func (bb *BatchBuffer) popAsyncFlushErrorLocked(targetTable string) error {
	if len(bb.asyncFlushErrs) == 0 {
		return nil
	}
	var matchedErr error
	kept := bb.asyncFlushErrs[:0]
	for _, entry := range bb.asyncFlushErrs {
		if matchTargetTable(entry.sample, targetTable) {
			if matchedErr == nil {
				matchedErr = entry.err
			}
		} else {
			kept = append(kept, entry)
		}
	}
	bb.asyncFlushErrs = kept
	return matchedErr
}

